CREATE INDEX idx_users_email ON users (email);

-- Does NOT use idx_users_email -- the index stores raw email values,
-- not their lowercased form, so it has nothing matching this expression.
EXPLAIN SELECT * FROM users WHERE lower(email) = 'amy@example.com';
-- Seq Scan on users
--   Filter: (lower(email) = 'amy@example.com'::text)

-- Fix: index the expression itself, not just the raw column.
CREATE INDEX idx_users_email_lower ON users (lower(email));

EXPLAIN SELECT * FROM users WHERE lower(email) = 'amy@example.com';
-- Index Scan using idx_users_email_lower on users
--   Index Cond: (lower(email) = 'amy@example.com'::text)

CREATE INDEX idx_orders_status ON orders (status);

-- Suppose 95% of orders.status = 'active', and only 5% are 'cancelled'.

EXPLAIN SELECT * FROM orders WHERE status = 'active';
-- Seq Scan on orders
--   Filter: (status = 'active'::text)
-- (planner ignores idx_orders_status -- correctly)

EXPLAIN SELECT * FROM orders WHERE status = 'cancelled';
-- Index Scan using idx_orders_status on orders
--   Index Cond: (status = 'cancelled'::text)
-- (planner uses the SAME index here -- also correctly)

