examples.code:
-- Session 1 (T1)                          -- Session 2 (T2)
BEGIN;
UPDATE accounts SET balance = 0
  WHERE id = 1;
-- (not yet committed)

                                             BEGIN ISOLATION LEVEL READ UNCOMMITTED;
                                             SELECT balance FROM accounts WHERE id = 1;
                                             -- In a database that truly implements
                                             -- READ UNCOMMITTED, this would see 0.
                                             -- In PostgreSQL, it instead sees the
                                             -- last COMMITTED value -- T1's change
                                             -- is invisible until T1 commits.

ROLLBACK;   -- T1's change to balance never actually happened

-- Session 1 (T1), READ COMMITTED (the default)   -- Session 2 (T2)
BEGIN;
SELECT balance FROM accounts WHERE id = 1;
-- sees 500

                                                    UPDATE accounts SET balance = 400
                                                      WHERE id = 1;
                                                    COMMIT;

SELECT balance FROM accounts WHERE id = 1;
-- sees 400 -- a DIFFERENT answer to the SAME
-- question, within the SAME transaction
COMMIT;

-- ---- Repeated under REPEATABLE READ instead ----
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT balance FROM accounts WHERE id = 1;
-- sees 500

                                                    UPDATE accounts SET balance = 400
                                                      WHERE id = 1;
                                                    COMMIT;

SELECT balance FROM accounts WHERE id = 1;
-- STILL sees 500 -- T1's snapshot was taken once,
-- at the transaction's start, and T2's commit is
-- simply invisible to it
COMMIT;

-- Session 1 (T1), READ COMMITTED (the default)   -- Session 2 (T2)
BEGIN;
SELECT COUNT(*) FROM tickets WHERE status = 'pending';
-- sees 3

                                                    INSERT INTO tickets (status)
                                                      VALUES ('pending');
                                                    COMMIT;

SELECT COUNT(*) FROM tickets WHERE status = 'pending';
-- sees 4 -- a new row "phantom-appeared" between
-- two runs of the identical query, in the same transaction
COMMIT;

-- Under REPEATABLE READ, T1's single transaction-wide snapshot
-- was taken before T2's INSERT committed, so T2's new row is
-- invisible to BOTH of T1's counts -- both would report 3.

