COMMIT;

exercises.solutionCode:
-- Fix 1: SERIALIZABLE, with a retry loop in the application
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT seats_remaining FROM flights WHERE id = 1;
UPDATE flights SET seats_remaining = seats_remaining - 1 WHERE id = 1;
INSERT INTO bookings (flight_id, customer_id) VALUES (1, /* customer */);
COMMIT;
-- if this raises a serialization_failure error, the application must
-- catch it and retry the entire transaction from BEGIN

-- Fix 2: explicit row locking with SELECT ... FOR UPDATE
BEGIN;
SELECT seats_remaining FROM flights WHERE id = 1 FOR UPDATE;
-- this blocks a concurrent second transaction's FOR UPDATE on the same
-- row until the first one commits or rolls back, so the second
-- transaction re-reads the ALREADY-UPDATED value once it proceeds
UPDATE flights SET seats_remaining = seats_remaining - 1 WHERE id = 1;
INSERT INTO bookings (flight_id, customer_id) VALUES (1, /* customer */);
COMMIT;
